contracts.obligation:
let buf = [1u8, 2, 3, 4, 5, 6, 7, 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let recv = VmReader::from(&buf[..]);
let out = recv.has_remain();
assert(out);

let buf = [1u8, 2, 3, 4, 5, 6, 7, 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmReader::from(&buf[..]);
recv.limit(4);
assert(recv.remain_spec() <= 4);

let buf = [1u8, 2, 3, 4, 5, 6, 7, 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmReader::from(&buf[..]);
let before = recv.cursor.vaddr;
recv.skip(4);
assert(recv.cursor.vaddr == before + 4);

let mut buf = [0u8; 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let recv = VmWriter::from(&mut buf[..]);
let out = recv.has_avail();
assert(out);

let mut buf = [0u8; 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmWriter::from(&mut buf[..]);
recv.limit(4);
assert(recv.avail_spec() <= 4);

let mut buf = [0u8; 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmWriter::from(&mut buf[..]);
let before = recv.cursor.vaddr;
recv.skip(4);
assert(recv.cursor.vaddr == before + 4);

let mut buf = [0u8; 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmWriter::from(&mut buf[..]);
assert(recv.avail_spec() == 8usize);

let recv = Mutex::<u64>::new(5u64);
let out = recv.lock();
assert(out.view() == 5u64);
let _held = out;

let recv = RcuOption::<alloc::boxed::Box<u64>>::new_none();
let out = recv.read();
let flag = out.is_none();
assert(flag);
let _held = out;

let recv = RcuOption::<alloc::boxed::Box<u64>>::new(Some(alloc::boxed::Box::new(5u64)));
let handle = recv.read();
let flag = handle.is_none();
assert(!flag);
let _held = handle;

let recv = RcuOption::<alloc::boxed::Box<u64>>::new(Some(alloc::boxed::Box::new(5u64)));
let out = recv.read();
let flag = out.is_none();
assert(!flag);
let _held = out;

let recv = RwArc::new(5u64);
let ro = recv.clone_ro();
let out = ro.read();
assert(out.view() == 5u64);
let _held = out;

let recv = RwArc::new(5u64);
let out = recv.get_cloned();
assert(out == 5u64);

let recv = RwLock::<u64, PreemptDisabled>::new(5u64);
let out = recv.read();
assert(out.view() == 5u64);
let _held = out;

let recv = RwLock::<u64, PreemptDisabled>::new(5u64);
let out = recv.read();
assert(out.view() == 5u64);
let _held = out;

let recv = RwLock::<u64, PreemptDisabled>::new(5u64);
if let Some(out) = recv.try_read() {
    assert(out.view() == 5u64);
    let _held = out;
}

let recv = RwMutex::<u64>::new(5u64);
let out = recv.read();
assert(out.view() == 5u64);
let _held = out;

let recv = RwMutex::<u64>::new(5u64);
let out = recv.read();
assert(out.view() == 5u64);
let _held = out;

let recv = RwMutex::<u64>::new(5u64);
if let Some(out) = recv.try_read() {
    assert(out.view() == 5u64);
    let _held = out;
}

let recv = WaitQueue::new();
let out = recv.wake_all();
assert(out == 0usize);

let recv = Either::<u64, u64>::Left(5u64);
let out = recv.left();
assert(out == Some(5u64));

let recv = Either::<u64, u64>::Right(5u64);
let out = recv.right();
assert(out == Some(5u64));
